"use strict";

const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const read = (file) => fs.readFileSync(path.join(root, file), "utf8").trim();
const icons = read("vendor/phosphor/icons.css").replaceAll(
  'url("./',
  'url("../vendor/phosphor/',
);

const bundle = [
  "/* Generated by scripts/build-home-css.js. */",
  read("css/tailwind.css"),
  read("css/styles.css"),
  icons,
].join("\n");

fs.writeFileSync(path.join(root, "css/home-bundle.css"), bundle + "\n");
console.log(`css/home-bundle.css: ${Buffer.byteLength(bundle)} bytes`);
